"use client";

import Link from "next/link";
import * as React from "react";

export interface LinkableProps {
  href?: string | undefined;
  external?: boolean | undefined;
  target?: string | undefined;
  rel?: string | undefined;
  as?: React.ElementType | undefined;
}
export const useLinkableComponent = <T extends LinkableProps>({
  href,
  external,
  as = "div",
  ...rest
}: T) => {
  const isExternal =
    external ??
    (href?.startsWith("http") ||
      href?.startsWith("mailto:") ||
      href?.startsWith("tel:"));
  if (href) {
    if (isExternal) {
      return {
        Component: "a" as const,
        href,
        linkProps: {
          rel: "noopener noreferrer",
          target: "_blank",
          ...rest,
        },
      };
    }
    return {
      Component: Link,
      href,
      linkProps: {
        ...rest,
      },
    };
  }
  return {
    Component: as,
    href,
    linkProps: {
      ...rest,
    },
  };
};

"use client";

import * as React from "react";

import { processColor } from "@/lib/process-color";
import type { ReactFC } from "@/lib/types";
import { useLinkableComponent } from "@/registry/hooks/useLinkableComponent";
import { ConditionalTooltip } from "@/registry/new-york/conditional-tooltip/ConditionalTooltip";
import {
  getButtonContent,
  getFinalIconSize,
} from "@/registry/new-york/custom-button/CustomButtonContent";
import * as CustomButtonStylesModule from "@/registry/new-york/custom-button/CustomButtonStyles";
import { borderVariantKey } from "@/registry/new-york/custom-button/CustomButtonStyles";
import type * as CustomButtonTypesModule from "@/registry/new-york/custom-button/CustomButtonTypes";

const DEFAULT_LIGHT_COLOR = "bg-zinc-900";
const DEFAULT_DARK_COLOR = "bg-zinc-100";
const EMPTY_CLASS_NAMES: NonNullable<CustomButtonProps["classNames"]> = {};
export const { buttonVariants } = CustomButtonStylesModule;
export const { defaultIconSizes } = CustomButtonStylesModule;
export const { sizeStyles } = CustomButtonStylesModule;
export const { spinnerSizeMap } = CustomButtonStylesModule;
export type ButtonVariantsProps = CustomButtonStylesModule.ButtonVariantsProps;
export type CustomButtonProps = CustomButtonTypesModule.CustomButtonProps;
export type CustomButtonVariant = CustomButtonTypesModule.CustomButtonVariant;
export const CustomButton: ReactFC<CustomButtonProps> = ({
  className,
  variant = "filled",
  size = "md",
  circle = false,
  color,
  darkColor,
  style,
  icon: Icon,
  iconSize,
  leftIcon: LeftIcon,
  rightIcon: RightIcon,
  leftSide,
  rightSide,
  loading,
  children,
  classNames = EMPTY_CLASS_NAMES,
  href,
  external,
  disabled = false,
  as = "button",
  tooltip,
  ...props
}) => {
  const { Component, linkProps } = useLinkableComponent({
    as,
    external,
    href,
    ...props,
  });
  const finalColorValue = color || DEFAULT_LIGHT_COLOR;
  const finalDarkColorValue = darkColor ?? (color || DEFAULT_DARK_COLOR);
  const finalColor = processColor(finalColorValue);
  const finalDarkColor = processColor(finalDarkColorValue);
  const finalIconSize = getFinalIconSize(size, iconSize);
  const hasIcon = Boolean(Icon || LeftIcon || RightIcon);
  const isIconOnly = circle || (!children && hasIcon);
  const buttonContent = getButtonContent({
    Icon,
    LeftIcon,
    RightIcon,
    children,
    classNames,
    finalIconSize,
    isIconOnly,
    leftSide,
    loading,
    rightSide,
    size,
  });
  const buttonAttributes = {
    className: buttonVariants({
      class: className,
      isIconButton: isIconOnly,
      [borderVariantKey]: circle ? "circle" : "default",
      size,
      variant,
    }),
    style: {
      "--button-color": `var(--color-${finalColor})`,
      "--button-dark-color": `var(--color-${finalDarkColor})`,
      ...style,
    } satisfies React.CSSProperties & {
      "--button-color": string;
      "--button-dark-color": string;
    },
    ...linkProps,
    ...props,
  };
  const button = (
    <Component
      {...buttonAttributes}
      disabled={Component === "button" ? disabled || loading : undefined}
      href={href}
    >
      {buttonContent}
    </Component>
  );

  return tooltip ? (
    <ConditionalTooltip
      content={String(tooltip)}
      condition={true}
      classNames={{
        tooltip: classNames.tooltip,
      }}
    >
      {button}
    </ConditionalTooltip>
  ) : (
    button
  );
};
CustomButton.displayName = "CustomButton";

import * as React from "react";

import type { Size } from "@/lib/types";
import { cn } from "@/lib/utils";
import {
  defaultIconSizes,
  sizeStyles,
} from "@/registry/new-york/custom-button/CustomButtonStyles";
import type { CustomButtonProps } from "@/registry/new-york/custom-button/CustomButtonTypes";
import { Spinner } from "@/registry/new-york/spinner/Spinner";

export const getFinalIconSize = (size: Size, iconSize?: number | undefined) => {
  const foundSizeStyle = sizeStyles[size];
  if (!foundSizeStyle) {
    throw new Error(`Invalid size: ${size}`);
  }
  return iconSize ?? foundSizeStyle.iconSize ?? defaultIconSizes[size];
};
const renderIcon = ({
  IconComponent,
  className,
  classNames,
  finalIconSize,
}: {
  IconComponent?: React.ElementType | undefined;
  className?: string | undefined;
  classNames: NonNullable<CustomButtonProps["classNames"]>;
  finalIconSize: number;
}) =>
  IconComponent && (
    <IconComponent
      aria-hidden="true"
      focusable="false"
      size={finalIconSize}
      className={cn(classNames.icon, "shrink-0", className)}
    />
  );
export const getButtonContent = ({
  Icon,
  LeftIcon,
  RightIcon,
  children,
  classNames,
  finalIconSize,
  isIconOnly,
  leftSide,
  loading,
  rightSide,
  size,
}: {
  Icon?: React.ElementType | undefined;
  LeftIcon?: React.ElementType | undefined;
  RightIcon?: React.ElementType | undefined;
  children: React.ReactNode;
  classNames: NonNullable<CustomButtonProps["classNames"]>;
  finalIconSize: number;
  isIconOnly: boolean;
  leftSide: React.ReactNode;
  loading?: boolean | undefined;
  rightSide: React.ReactNode;
  size: Size;
}) => {
  const icon = (IconComponent?: React.ElementType | undefined) =>
    renderIcon({
      IconComponent,
      classNames,
      finalIconSize,
    });
  if (loading) {
    return (
      <>
        <Spinner size={size} className="shrink-0 text-current" />
        {!isIconOnly && <span className="truncate">{children}</span>}
      </>
    );
  }
  return (
    <>
      {leftSide || icon(LeftIcon)}
      {Icon
        ? icon(Icon)
        : children && <span className="truncate">{children}</span>}
      {rightSide || icon(RightIcon)}
    </>
  );
};

import * as React from "react";
import { tv } from "tailwind-variants";

import type { Size } from "@/lib/types";

interface SizeStyle {
  iconSize?: number;
}
export const sizeStyles: Record<Size, SizeStyle> = {
  lg: {
    iconSize: 20,
  },
  md: {
    iconSize: 16,
  },
  sm: {
    iconSize: 16,
  },
  xl: {
    iconSize: 24,
  },
  xs: {
    iconSize: 14,
  },
};
export const spinnerSizeMap: Record<Size, number> = {
  lg: 20,
  md: 16,
  sm: 16,
  xl: 24,
  xs: 14,
};
export const defaultIconSizes: Record<Size, number> = {
  lg: 20,
  md: 16,
  sm: 16,
  xl: 24,
  xs: 14,
};
// Preserve the published variant key while naming the local value for its role.
export const borderVariantKey = "shape";

export const buttonVariants = tv({
  base: "focus-visible:ring-ring inline-flex cursor-pointer items-center justify-center gap-2 rounded-md font-medium whitespace-nowrap transition-all focus-visible:ring-1 focus-visible:outline-hidden active:scale-95 disabled:pointer-events-none disabled:opacity-50",
  compoundVariants: [
    {
